-- 1) New source for 848 (UAEU page; 501 repoints its existing source below)
INSERT INTO sources (id, url, title, domain, source_type, accessed_at, is_official, is_verified, created_at) VALUES (3116, 'https://www.uaeu.ac.ae/en/admission/undergraduate-scholarships.shtml', 'Undergraduate Scholarships | United Arab Emirates University (official)', 'uaeu.ac.ae', 'scholarship', now(), true, true, now()) RETURNING id, url;

-- 2) 501 → Khalifa University Graduate Scholarship for International Students, rel 10, upcoming, NULL/not_published
UPDATE scholarships SET title = 'Khalifa University Graduate Scholarship for International Students', provider = 'Khalifa University', coverage_type = 'Full Tuition + Stipend', amount_usd_value = 0, deadline = 'There is no separate scholarship application and no standalone scholarship deadline: scholarship eligibility is assessed as part of the admission process, and applicants should indicate their interest in scholarship support when submitting their admission application. Khalifa University admits postgraduates by semester - at the time this record was verified, the university stated that postgraduate admissions for Spring 2027 were closed, and no dated deadline for the next intake was published on the pages read, so no deadline_date is recorded. Watch the Postgraduate Admissions page for the next (Fall) cycle and apply for admission in that window.', deadline_date = NULL, deadline_type = 'not_published', deadline_range_start = NULL, deadline_range_end = NULL, degree_levels = $j$["Master's", "PhD"]$j$, eligible_majors = $j$["Full-time graduate programmes at Khalifa University of Science and Technology (master's and PhD across science, engineering, computing and health); the PhD Study Path Tiers III-IV are also open to part-time students"]$j$, eligible_countries = $j$["International students enrolled in Khalifa University graduate programmes on a full-time basis (UAE nationals have parallel scholarship variants, and Chinese nationals a joint CSC-KU PhD scheme - neither is this record)"]$j$, min_gpa = NULL, min_ielts = NULL, financial_need_based = false, merit_based = true, description = $desc$Khalifa University's Graduate Scholarship for International Students is the tiered funding system through which the Abu Dhabi research university supports its international master's and PhD students - and there is no separate scholarship application: eligibility is assessed inside the admission process (you indicate your interest in scholarship support in the admission application), slots are limited, and every applicant is mapped to a scholarship tier on academic merit and other factors aligned with the university's strategic priorities, with the university stressing that meeting the minimum criteria does not guarantee an award. For master's students the tiers are tuition-centred and carry no stipend: Tiers I and II give full coverage of tuition fees plus free university accommodation for eligible full-time students, textbooks, medical insurance, mobilization and demobilization flights for overseas students and coverage of UAE visa fees; Tier III is a 50% tuition waiver with the same support items except accommodation; Tier IV provides the support items (textbooks, medical insurance, flights, visa fees) without a tuition waiver. For PhD students there are two paths, and the difference between them is the single most important thing to understand. The Research Path (full-time only, reassessed annually) pays at senior level - Tier I: full tuition plus a basic monthly stipend of AED 20,000 and an additional monthly allowance of AED 20,000 (subject to approval and progression criteria), Tier II the same with AED 10,000 additional, Tier III a 75% tuition waiver plus AED 20,000 monthly stipend, Tier IV a 50% waiver plus free accommodation - but every tier carries a commitment to work with Khalifa University or a nominated entity after graduation for a period equivalent to your period of study (the university may still choose not to offer you a post). The Study Path has no work commitment but far smaller cash: Tier I full tuition plus AED 4,000 per month and free accommodation, Tier II 75% waiver plus AED 2,000 per month, Tiers III and IV 50% and 25% waivers (also open part-time), all with textbooks, conference support (subject to approval), medical insurance, flights and visa fees, and annual reassessment. Continued eligibility across the board is subject to CGPA and programme-progression requirements, and the university expressly reserves the right to change published benefits without prior notice, so treat the tier tables as the current published position rather than a guarantee. Undergraduates are a different scheme altogether (catalogue record 854).$desc$, requirements = $req$Everything runs through postgraduate admission: apply online for a master's or PhD programme during an admission cycle (Spring 2027 admissions were stated as closed when this record was verified), indicate your interest in scholarship support in the application, and the university assigns scholarship tiers on academic merit (plus research potential at PhD level) and strategic fit - slots are limited and meeting the minima does not guarantee a scholarship. Admission minima are published and route-specific: master's applicants need a relevant bachelor's degree with CGPA at least 3.0/4.0; regular PhD applicants need a bachelor's of at least 3.0 and a master's of at least 3.25; direct-PhD applicants (no master's) need a bachelor's of at least 3.5 plus a GRE general quantitative score of at least 150 with all sections attempted (test-centre only). English for both levels is IELTS 6.5 overall or TOEFL iBT 91 (test-centre; Home Edition not accepted; TOEFL code 0960), with exemptions possible for native speakers and some English-medium graduates - but every applicant must still upload English evidence. The file also needs two referee recommendations (online form), a statement of purpose of 500-1,000 words (plus a research statement for PhD), an admission interview, certified degree certificates and transcripts showing the grading scale, an application fee of AED 200, and - plan well ahead for this one - a UAE Ministry of Education equivalency certificate for degrees earned outside the UAE, which the university warns is a lengthy process. If funded, read your tier conditions closely: PhD Research Path tiers are reassessed annually and bind you to post-graduation work for the university or a nominated entity for a period equal to your study period, additional PhD allowances depend on approval and progression criteria, and continued eligibility everywhere is subject to CGPA and progression requirements; benefits can change without prior notice. The route-specific CGPA figures (3.0 / 3.25 / 3.5) and the exemption-qualified English rule are admission gates rather than one scheme-wide minimum, so min_gpa/min_ielts are not recorded.$req$, website_url = 'https://www.ku.ac.ae/scholarship/graduate-research-teaching-scholarship-for-international-students', source_url = 'https://www.ku.ac.ae/scholarship/graduate-research-teaching-scholarship-for-international-students', application_url = 'https://www.ku.ac.ae/postgraduate-admissions', recurrence = 'annual', application_status = 'upcoming', verification_status = 'verified', source_reliability = 10, is_active = true, last_verified_at = now(), last_updated_at = now(), notes = $note$REWRITTEN 2026-10-28 (cleanup pass 117) from Khalifa University official pages fetched the same day: the 'Graduate Scholarship for International Students' page (scholarships for qualified international students enrolled in graduate programs full-time, benefits subject to change without prior notice; master's tiers - I & II full tuition coverage plus textbooks, free university accommodation for eligible full-time students, medical insurance, mobilization/demobilization flights and UAE visa fee coverage; III 50% tuition waiver plus textbooks/medical/flights/visa; IV textbooks/medical/flights/visa only; scholarship eligibility assessed as part of admission with no separate application, limited slots, tier mapping on academic merit and strategic priorities, minimum criteria not guaranteeing an award; PhD Research Path with work commitment, full-time only, annual reassessment - Tier I full tuition + basic stipend AED 20,000/month + additional allowance AED 20,000/month subject to approval and progression criteria, Tier II full tuition + 20,000 + 10,000, Tier III 75% waiver + AED 20,000/month stipend, Tier IV 50% waiver + free accommodation, all with textbooks, conference support subject to approval, medical insurance, flights, visa fees and a commitment to work with Khalifa University or a nominated entity upon graduation for a period equivalent to the period of study, the university reserving the right not to offer a post; PhD Study Path without work commitment, annual reassessment - Tier I full tuition + AED 4,000/month + free accommodation, Tier II 75% waiver + AED 2,000/month, Tier III 50% and Tier IV 25% waivers open also to part-time students, all with the same support items), the 'Postgraduate Scholarships' landing page (competitive merit-based programmes; awards on academic achievement, research potential, field of study and strategic alignment; continued eligibility subject to CGPA and progression requirements; applicants indicate scholarship interest in the admission application; the Combined Master-PhD scheme is for UAE nationals only and the CSC-KU Joint PhD Scholarship - Chinese nationals, KU stipend AED 9,200/month plus CSC support, Fall-only deadline 10 February - is a separate scheme, neither recorded here), and the 'Postgraduate Admissions' page ('Postgraduate admissions for Spring 2027 are closed' at verification; admission minima - master's CGPA 3.0/4.0, regular PhD bachelor's 3.0 + master's 3.25, direct PhD bachelor's 3.5 + GRE quantitative 150 with all sections attempted; English IELTS 6.5 or TOEFL iBT 91 test-centre only, code 0960, exemptions for native speakers and some English-medium graduates with evidence upload still mandatory; two referees, statement of purpose and PhD research statement 500-1,000 words, interview; application fee AED 200; UAE MOE equivalency certificate for non-UAE degrees with a 'lengthy process' warning). The stored row was an unverified all-levels placeholder behind an invented 'International Excellence Scholarship' title and a generic admissions URL; it is re-anchored to the university's named graduate scheme for international students, with degree_levels corrected from [Bachelor's, Master's, PhD] to [Master's, PhD] because the international undergraduate tiers are already covered by record 854. deadline_date NULL/'not_published' with status 'upcoming' (current admission cycle closed; the scholarship itself has no standalone deadline). Award stored as NULL (AED, 'variable', 'variable') because benefits are tiered across two degree levels and two PhD paths; amount_usd_value 0 (non-USD); min_gpa/min_ielts NULL (route-specific admission gates: CGPA 3.0/3.25/3.5; English rule has exemptions). Note the scholarship page carries a 13 June 2023 publication date - it remains the page linked from the current site and is corroborated by the current landing page, but the university states benefits may change without notice. university_scholarships row 487 synced (us 406 belongs to the undergraduate record 854, untouched); source 888 (exclusive to this record; target URL pre-checked free) repointed from the bare ku.ac.ae homepage to the graduate scholarship page.$note$, award_amount = NULL, award_currency = 'AED', award_period = 'variable', award_basis = 'variable', living_allowance = NULL, funding_type = 'Tiered graduate funding assigned at admission (no separate application): Masters Tiers I-II full tuition + free accommodation + textbooks + medical insurance + flights + visa fees (no stipend), Tier III 50% waiver, Tier IV support items only; PhD Research Path full tuition + AED 20,000/month basic stipend + AED 10,000-20,000 additional allowance at top tiers (75%/50% waivers below) in exchange for a post-graduation work commitment equal to the study period; PhD Study Path (no commitment) full/75%/50%/25% waivers with AED 4,000 or 2,000/month at the top two tiers', tuition_coverage = 'From full tuition coverage (Masters Tiers I-II; PhD Research Path Tiers I-II; PhD Study Path Tier I) down through 75%, 50% and 25% waivers by tier and path - always read together with the tier extras (accommodation, stipends, flights, insurance, visa fees) and the Research Path work commitment.', english_requirements = 'Graduate admission English minimum: overall academic IELTS 6.5 or TOEFL iBT 91 (test centre only; Home Edition not accepted; TOEFL code 0960), with exemptions possible for native English speakers and some English-medium graduates - evidence upload is still mandatory for all applicants. (min_ielts not recorded - admission gate with exemptions.)', required_documents = $j$["Online postgraduate admission application (fee AED 200) with scholarship interest indicated - there is no separate scholarship application", "Certified bachelor's (and master's, as applicable) degree certificates and official transcripts showing the grading scale", "UAE Ministry of Education equivalency certificate for degrees from outside the UAE (start early - the university warns it is a lengthy process)", "English proficiency certificate (IELTS 6.5 / TOEFL iBT 91, test-centre; uploaded by every applicant even if exemption-eligible)", "Two referee recommendations via the online form; statement of purpose (500-1,000 words); research statement (PhD); GRE general test for direct-PhD applicants; admission interview"]$j$, expected_opening_period = NULL, expected_deadline_period = NULL, rounds = $json$[{"cycle": "Spring 2027 postgraduate admissions", "status": "closed", "note": "Stated as closed on the Postgraduate Admissions page when this record was verified (2026-10-28)"}, {"pattern": "Semester-based (Fall/Spring) postgraduate intakes; the scholarship tier is assigned during admission to full-time international applicants who indicate scholarship interest - slots are limited and minimum criteria do not guarantee an award"}]$json$ WHERE id = 501 RETURNING id, title, source_reliability;

-- 3) 848 → Chancellor's Scholarship for Elite Students (UAEU), rel 10, open, NULL/not_published
UPDATE scholarships SET title = 'Chancellor''s Scholarship for Elite Students (UAEU)', provider = 'United Arab Emirates University (UAEU)', coverage_type = 'Tuition Waiver', amount_usd_value = 0, deadline = 'There is no separate scholarship deadline: for new students the scholarship application is submitted as part of the university admission application during the official, announced undergraduate admission periods (UAEU admits new undergraduates for both the first and the second semester). Enrolled students who meet the conditions may also apply within one academic year of their high-school graduation, and continuing students apply after grades are released on the dates in the University Academic Calendar. Apply for admission in the normal undergraduate window with your Grade 12 results and English (and, where applicable, mathematics/Arabic) test scores ready.', deadline_date = NULL, deadline_type = 'not_published', deadline_range_start = NULL, deadline_range_end = NULL, degree_levels = $j$["Bachelor's"]$j$, eligible_majors = $j$["All undergraduate programmes at United Arab Emirates University; note the test conditions differ by college - the mathematics requirement does not apply to the College of Business and Economics, College of Humanities and Social Sciences, College of Education and College of Law, and the Arabic proficiency requirement applies to Law only"]$j$, eligible_countries = $j$["New undergraduate students admitted from the academic year 2025/2026 onwards under UAEU's Scholarship Students categories - international students (enrolled from inside or outside the UAE) and children of UAEU faculty members and staff", "Top-performing high school graduates: Grade 12 average of at least 98% (100% tuition discount) or at least 95% (75% discount), plus the English (and mathematics/Arabic where applicable) test scores published for each level"]$j$, min_gpa = NULL, min_ielts = NULL, financial_need_based = false, merit_based = true, description = $desc$The Chancellor's Scholarship for Elite Students is United Arab Emirates University's flagship undergraduate merit award - 'one of its leading initiatives to attract top-performing high school graduates' - paid as a discount on tuition fees under the university's Scholarship Students policy (the conditions recorded here apply to new students admitted from 2025/2026 onwards; eligibility alone is not an entitlement, because awards depend on the availability of allocated scholarship seats). It comes in two grant levels under one name. The 100% discount requires a Grade 12 average of at least 98%, plus English at Academic IELTS 7.5 (or TOEFL ITP 590 / iBT 105 / CPT 233) and, for most colleges, mathematics at SAT-MATH 730 or ACT-MATH 32 (the maths condition does not apply to Business and Economics, Humanities and Social Sciences, Education or Law; Law instead requires Arabic at 6.5 in the Al Ain Arabic Language Test). The 75% discount lowers the bar to 95% in Grade 12 with IELTS 6.5 (TOEFL ITP 550 / iBT 85 / CPT 193), SAT-MATH 660 or ACT-MATH 28 and Arabic 5.5 for Law. In both cases the discount is on tuition fees only - housing and admission application fees are expressly not covered, repeated courses are not covered, and no cash refund is paid in exchange - and you sign a scholarship contract before benefiting. Keeping it is demanding: a cumulative GPA of at least 3.8 at the 100% level (3.6 at 75%), at least 15 credit hours per regular semester, no other scholarship held, completion within the programme's normal semesters, performance evaluated every semester - and changing your college or programme cancels the scholarship (you may reapply under the rules then in force), while an improvement in cumulative GPA over two consecutive semesters can support an upgrade request, and appeals must be filed within 30 days of a cancellation notice. New students apply inside the ordinary admission application; the same page carries sibling awards (a talent-based Chancellor's Scholarship and one for children of UAEU employees), which are separate schemes and not this record.$desc$, requirements = $req$For the 100% tuition discount: at least 98% in the General Secondary School Certificate (Grade 12) or equivalent, all general and college-specific admission requirements met, English at Academic IELTS 7.5 (or TOEFL ITP 590, iBT 105, CPT 233), mathematics at SAT-MATH 730 or ACT-MATH 32 for all colleges except Business and Economics, Humanities and Social Sciences, Education and Law, and (Law only) Arabic at least 6.5 in the Al Ain Arabic Language Test. For the 75% discount: at least 95% in Grade 12, IELTS 6.5 (ITP 550 / iBT 85 / CPT 193), SAT-MATH 660 or ACT-MATH 28 on the same college exceptions, and Arabic 5.5 for Law. New students submit the scholarship application as part of the university admission application during the official undergraduate admission periods (the page applies to students admitted from 2025/2026 onwards, in the categories of international students - enrolled from inside or outside the UAE - and children of UAEU faculty and staff); students already enrolled who meet the conditions may apply within one academic year of high-school graduation, and continuing students apply for a new scholarship, an upgrade or an appeal after grades are released per the University Academic Calendar. Before benefiting you must sign the scholarship contract. Continuation then requires: cumulative GPA of at least 3.8 (100% level) or 3.6 (75% level), at least 15 credit hours per regular semester, no other scholarship (a student may hold only one and cannot combine), finishing within the normal semesters of the study plan, and clean academic/behavioural standing - performance is evaluated each semester; be aware that changing college or programme cancels the award (a fresh application is possible), the discount never covers repeated courses, housing or admission fees, is not retroactive and cannot be exchanged for a refund, and appeals against cancellation must reach the committee within 30 days. Entry is set in Grade-12 percentages and the IELTS figure differs by grant level (7.5 vs 6.5), so min_gpa/min_ielts are not recorded.$req$, website_url = 'https://www.uaeu.ac.ae/en/admission/undergraduate-scholarships.shtml', source_url = 'https://www.uaeu.ac.ae/en/admission/undergraduate-scholarships.shtml', application_url = 'https://uaeu.elluciancrmrecruit.com/Apply/Account/Login', recurrence = 'annual', application_status = 'open', verification_status = 'verified', source_reliability = 10, is_active = true, last_verified_at = now(), last_updated_at = now(), notes = $note$REWRITTEN 2026-10-28 (cleanup pass 117) from United Arab Emirates University's official 'Undergraduate Scholarships' page, fetched first-hand in full (4 chunks) the same day. The stored invented-seeming title turned out to be the official scheme name. The page states: a tuition-fees discount is granted to students enrolled under the 'Scholarship Students' category per approved policies aligned with the Federal Higher Education Institutions Governance Resolution; meeting eligibility criteria is not an entitlement and awards depend on allocated scholarship seats; from 2025/2026 the categories are international students (enrolled from inside or outside the UAE) and children of UAEU faculty members and staff; earlier-admitted students keep prior conditions. Chancellor's Scholarship for Elite Students, 100% discount: Grade 12 minimum 98%, admission requirements, English TOEFL ITP 590 / iBT 105 / CPT 233 / Academic IELTS 7.5, mathematics SAT-MATH 730 / ACT-MATH 32 for all colleges except Business and Economics, Humanities and Social Sciences, Education and Law, Arabic minimum 6.5 (Al Ain Arabic Language Test) for Law only; benefit 100% discount on tuition fees only (housing and admission application fees excluded); continuation CGPA at least 3.8, at least 15 credit hours per regular semester, no other scholarship, normal study-plan duration, programme/major/load changes may affect continuation, revocation for integrity/regulation violations. 75% discount level: Grade 12 minimum 95%, IELTS 6.5 (ITP 550 / iBT 85 / CPT 193), SAT-MATH 660 / ACT-MATH 28, Arabic 5.5 for Law, continuation CGPA at least 3.6 and otherwise the same terms. Application: new students inside the admission application during official undergraduate admission periods (application_url is the Ellucian admission-portal login linked from the page); continuing students after grade release per the University Academic Calendar via the linked PowerApps form. General rules: only one scholarship may be held and scholarships cannot be combined; tuition only; minors covered if in the approved college plan; repeated courses not covered; semesterly performance evaluation; not retroactive; no refund in exchange; signed scholarship contract required; enrolled students may apply within one academic year of high-school graduation; conditions may be amended with Board of Trustees approval and notice; the committee may upgrade a scholarship after improved CGPA over two consecutive semesters on request; changing college/programme cancels the award (new application possible); appeals within 30 days of the cancellation notice. Sibling schemes on the same page (Chancellor's Scholarship for Talented Students at 100%/50% for innovation, arts, sports and technology talent, and the Chancellor's Scholarship for Children of UAEU Employees at 100%) are NOT this record. deadline_date NULL/'not_published': the page sets no scholarship-specific date (applications ride the announced admission periods); status 'open' because the 2025/26-onwards policy is in force and the search-indexed version of this same page lists first-semester application months (May-July) and second-semester months (September-November), the latter covering the verification date. Award stored as NULL (AED, 'year', 'variable'): percentage discounts of 100%/75% by grant level; amount_usd_value 0; min_gpa/min_ielts NULL (percentage-based entry; IELTS 7.5 vs 6.5 by level; CGPA figures are continuation conditions). Scholarship terms previously unread (placeholder row at reliability 4); new source 3116 created and linked; university_scholarships row 368 synced from its importer-era values.$note$, award_amount = NULL, award_currency = 'AED', award_period = 'year', award_basis = 'variable', living_allowance = NULL, funding_type = 'Tuition-fee discount for new undergraduates: 100% (Grade 12 at least 98% plus IELTS 7.5 and college test conditions) or 75% (at least 95% plus IELTS 6.5); tuition only - housing and admission application fees are not covered; continuation requires CGPA 3.8 (100% level) or 3.6 (75% level) and at least 15 credit hours per semester', tuition_coverage = 'A 100% or 75% discount on tuition fees until graduation within the normal study-plan semesters (repeated courses excluded; minors covered if in the approved college plan); no cash refund and no housing or application-fee coverage.', english_requirements = 'By grant level: Academic IELTS 7.5 for the 100% discount (or TOEFL ITP 590 / iBT 105 / CPT 233) and IELTS 6.5 for the 75% discount (ITP 550 / iBT 85 / CPT 193); mathematics at SAT-MATH 730/660 or ACT-MATH 32/28 for most colleges, and Arabic 6.5/5.5 (Al Ain Arabic Language Test) for Law. (min_ielts not recorded - the figure differs by level.)', required_documents = $j$["University admission application during an official undergraduate admission period, with the scholarship application submitted as part of it", "General Secondary School Certificate (Grade 12) or equivalent showing at least 98% (100% discount) or 95% (75% discount)", "English test scores at the level's minima (IELTS 7.5 or 6.5, or the listed TOEFL equivalents); mathematics SAT/ACT scores where the college requires them; Al Ain Arabic Language Test score for Law", "Signed scholarship contract before benefiting from the award"]$j$, expected_opening_period = NULL, expected_deadline_period = NULL, rounds = $json$[{"pattern": "New-student applications are submitted as part of the admission application during UAEU's official undergraduate admission periods for the first and second semesters (the page's indexed version lists May-July and September-November); continuing students apply after grade release on University Academic Calendar dates, and enrolled students may apply within one academic year of high-school graduation"}]$json$ WHERE id = 848 RETURNING id, title, source_reliability;

