UPDATE university_scholarships SET scholarship_name = 'Khalifa University Graduate Scholarship for International Students', availability_status = 'international_students', funding_type = 'Tiered at admission (no separate application): Masters full tuition + accommodation at top tiers (no stipend); PhD Research Path full tuition + AED 20,000/mo basic stipend (+ up to AED 20,000 additional allowance) with a post-graduation work commitment; PhD Study Path waivers 100-25% with AED 4,000/2,000/mo at top tiers', max_scholarship = 'Full tuition + AED 20,000/month basic stipend + up to AED 20,000/month additional allowance (PhD Research Path Tier I, subject to approval/progression; work commitment applies)', covers_tuition = true, covers_living_expenses = true, valued_aspect = 'Academic merit and research potential mapped to tiers at admission (limited slots; meeting minima does not guarantee an award)', eligibility_notes = 'International full-time Masters/PhD applicants (indicate scholarship interest in the admission application); admission minima CGPA 3.0 (MSc), 3.0+3.25 (PhD), 3.5 + GRE Q150 (Direct PhD); English IELTS 6.5 / TOEFL iBT 91', official_url = 'https://www.ku.ac.ae/scholarship/graduate-research-teaching-scholarship-for-international-students', source_url = 'https://www.ku.ac.ae/scholarship/graduate-research-teaching-scholarship-for-international-students', verification_status = 'verified', last_verified_at = now() WHERE id = 487 RETURNING id;
